    return s_acronyms[idx];
}

// ============================================================
// UTILITY FUNCTIONS
// ============================================================

static std::string get_prog_name(const char* argv0) {
    // Extract program name from path
    std::string path(argv0);
    size_t pos = path.rfind('/');
    if (pos != std::string::npos) {
        return path.substr(pos + 1);
    }
    return path;
}

static std::string get_working_dir() {
    char buf[4096];
    if (getcwd(buf, sizeof(buf))) {
        return std::string(buf);
    }
    return ".";
}

static std::string get_executable_path(const char* argv0) {
    // Try to get the full path from /proc/self/exe
    char buf[4096];
    ssize_t len = readlink("/proc/self/exe", buf, sizeof(buf)-1);
    if (len > 0) {
        buf[len] = '\0';
        return std::string(buf);
    }
    return std::string(argv0);
}

static void print_banner(FILE* fp, const char* progname) {
    // Format: "   :-) GROMACS - <name>, <version> (-:"
    // Centered in 80 chars
    std::string middle = ":-) GROMACS - ";
    middle += progname;
    middle += ", ";
    middle += GMX_VERSION;
    middle += " (-:";

    int len = (int)middle.size();
    int pad = (80 - len) / 2;
    if (pad < 0) pad = 0;

    for (int i = 0; i < pad; i++) fprintf(fp, " ");
    fprintf(fp, "%s\n\n", middle.c_str());
}

static void print_exec_info(FILE* fp, const char* argv0, const std::vector<std::string>& args) {
    std::string exe_path = get_executable_path(argv0);
    std::string work_dir = get_working_dir();

    fprintf(fp, "Executable:   %s\n", exe_path.c_str());
    fprintf(fp, "Data prefix:  %s\n", DATA_PREFIX);
    fprintf(fp, "Working dir:  %s\n", work_dir.c_str());
    fprintf(fp, "Command line:\n  ");

    // Print command line (basename of argv0 + all args)
    std::string prog = get_prog_name(argv0);
    fprintf(fp, "%s", prog.c_str());
    for (size_t i = 0; i < args.size(); i++) {
        fprintf(fp, " %s", args[i].c_str());
    }
    fprintf(fp, "\n");
}

static void print_quote(FILE* fp) {
    fprintf(fp, "\n\nGROMACS reminds you: %s\n\n", get_quote());
}

