// Utility functions
static std::string get_prog_name(const char* argv0) {
    std::string s(argv0);
    size_t p = s.rfind('/');
    return (p != std::string::npos) ? s.substr(p+1) : s;
}

static std::string get_working_dir() {
    char buf[4096] = ".";
    getcwd(buf, sizeof(buf));
    return buf;
}

static std::string get_exec_path(const char* argv0) {
    char buf[4096];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf)-1);
    if (n > 0) { buf[n] = '\0'; return buf; }
    return argv0;
}

static void print_banner(FILE* fp, const char* prog) {
    std::string s = std::string(":-) GROMACS - ") + prog + ", " + GMX_VERSION + " (-:";
    int len = (int)s.size();
    int pad = (80 - len) / 2;
    for (int i = 0; i < pad; i++) fputc(' ', fp);
    fprintf(fp, "%s\n\n", s.c_str());
}

static void print_startup(FILE* fp, const char* argv0, int argc, char** argv, int cmd_start) {
    // Print the startup info block
    std::string exe = get_exec_path(argv0);
    std::string cwd = get_working_dir();
    std::string prog = get_prog_name(argv0);

    fprintf(fp, "Executable:   %s\n", exe.c_str());
    fprintf(fp, "Data prefix:  %s\n", DATA_PREFIX);
    fprintf(fp, "Working dir:  %s\n", cwd.c_str());
    fprintf(fp, "Command line:\n  %s", prog.c_str());
    for (int i = 1; i < argc; i++) fprintf(fp, " %s", argv[i]);
    fprintf(fp, "\n");
}

static void print_quote(FILE* fp) {
    fprintf(fp, "\n\nGROMACS reminds you: %s\n\n", get_quote());
}

// Backup a file before overwriting
static std::string backup_file(const std::string& fname) {
    struct stat st;
    if (stat(fname.c_str(), &st) != 0) return "";

    std::string base = fname;
    for (int n = 1; n <= 999; n++) {
        std::string bak = "./#" + base + "." + std::to_string(n) + "#";
        if (stat(bak.c_str(), &st) != 0) {
            // bak doesn't exist, use it
            rename(fname.c_str(), bak.c_str());
            return bak;
        }
    }
    return "";
}

// Error message format
static void gmx_error(const char* prog, const char* srcfile, int line,
                      const char* func, const char* title, const char* msg, ...) {
    char buf[4096];
    va_list ap;
    va_start(ap, msg);
    vsnprintf(buf, sizeof(buf), msg, ap);
    va_end(ap);

    fprintf(stderr, "\n-------------------------------------------------------\n");
    fprintf(stderr, "Program:     %s, version %s\n", prog, GMX_VERSION);
    fprintf(stderr, "Source file: %s (line %d)\n", srcfile, line);
    fprintf(stderr, "Function:    %s\n", func);
    fprintf(stderr, "\n%s:\n%s\n", title, buf);
    fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
    fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
    fprintf(stderr, "-------------------------------------------------------\n");
}

EOF

