}

// Error message format
static void gmx_error(const char* prog, const char* srcfile, int line,
                      const char* func, const char* title, const char* msg, ...) {
    char buf[4096];
    va_list ap;
    va_start(ap, msg);
    vsnprintf(buf, sizeof(buf), msg, ap);
    va_end(ap);

    fprintf(stderr, "\n-------------------------------------------------------\n");
    fprintf(stderr, "Program:     %s, version %s\n", prog, GMX_VERSION);
    fprintf(stderr, "Source file: %s (line %d)\n", srcfile, line);
    fprintf(stderr, "Function:    %s\n", func);
    fprintf(stderr, "\n%s:\n%s\n", title, buf);
    fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
    fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
    fprintf(stderr, "-------------------------------------------------------\n");
}

