" -qj     <real>             (0)\n"
"           qj\n"
" -sigfac <real>             (0.7)\n"
"           Factor in front of sigma for starting the plot\n";

// Write XVG file header
static void write_xvg_header(FILE* fp, const char* argv0, int argc, char** argv, const char* title,
                              const char* xlabel, const char* ylabel,
                              const char* s0_legend, const char* s1_legend) {
