// Write XVG file header
static void write_xvg_header(FILE* fp, const char* argv0, int argc, char** argv, const char* title,
                              const char* xlabel, const char* ylabel,
                              const char* s0_legend, const char* s1_legend) {
    time_t t = time(NULL);
    char tbuf[64];
    struct tm* tm = localtime(&t);
    strftime(tbuf, sizeof(tbuf), "%a %b %e %T %Y", tm);

    std::string exe = get_exec_path(argv0);
    std::string cwd = get_working_dir();
    std::string prog = get_prog_name(argv0);

    fprintf(fp, "# This file was created %s\n", tbuf);
    fprintf(fp, "# Created by:\n");
    fprintf(fp, "#       ");
    {
        std::string s = std::string(":-) GROMACS - gmx ") + prog + ", " + GMX_VERSION + " (-:";
        int len = (int)s.size();
        int pad = (80 - len) / 2;
        for (int i = 0; i < pad; i++) fputc(' ', fp);
        fprintf(fp, "%s\n", s.c_str());
    }
    fprintf(fp, "# \n");
    fprintf(fp, "# Executable:   %s\n", exe.c_str());
    fprintf(fp, "# Data prefix:  %s\n", DATA_PREFIX);
    fprintf(fp, "# Working dir:  %s\n", cwd.c_str());
    fprintf(fp, "# Command line:\n#   %s", prog.c_str());
    for (int i = 1; i < argc; i++) fprintf(fp, " %s", argv[i]);
    fprintf(fp, "\n");
    fprintf(fp, "# gmx %s is part of G R O M A C S:\n#\n", prog.c_str());
    fprintf(fp, "# %s\n#\n", get_acronym());
    fprintf(fp, "@    title \"%s\"\n", title);
    fprintf(fp, "@    xaxis  label \"%s\"\n", xlabel);
    fprintf(fp, "@    yaxis  label \"%s\"\n", ylabel);
    fprintf(fp, "@TYPE xy\n");
    fprintf(fp, "@ view 0.15, 0.15, 0.75, 0.85\n");
    fprintf(fp, "@ legend on\n");
    fprintf(fp, "@ legend box on\n");
    fprintf(fp, "@ legend loctype view\n");
    fprintf(fp, "@ legend 0.78, 0.8\n");
    fprintf(fp, "@ legend length 2\n");
    if (s0_legend) fprintf(fp, "@ s0 legend \"%s\"\n", s0_legend);
    if (s1_legend) fprintf(fp, "@ s1 legend \"%s\"\n", s1_legend);
}

struct SigepsParams {
    double c6, cn;
    int pow;
    double sig, eps;
    double A, B, C;
    double qi, qj;
    double sigfac;
    std::string outfile;
    bool w;
    bool sig_set, eps_set;  // were sig/eps explicitly set by user?
    bool backup;
};

static int run_sigeps(const char* argv0, int argc, char** argv, bool quiet) {
    std::string prog_name = std::string("gmx ") + get_prog_name(argv0);

    SigepsParams p;
    p.c6 = 0.001;
    p.cn = 1e-6;
    p.pow = 12;
    p.sig = 0.3;
    p.eps = 1.0;
    p.A = 100000;
    p.B = 32;
    p.C = 0.001;
    p.qi = 0;
    p.qj = 0;
    p.sigfac = 0.7;
    p.outfile = "potje.xvg";
    p.w = false;
    p.sig_set = false;
    p.eps_set = false;
    p.backup = true;

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "-help") {
            printf("%s", SIGEPS_HELP);
            return 0;
        } else if (arg == "-version") {
            do_print_version(stdout, argv0, argc, argv);
            return 0;
        } else if (arg == "-o") {
            if (i+1 < argc) p.outfile = argv[++i];
        } else if (arg == "-c6") {
            if (i+1 < argc) p.c6 = atof(argv[++i]);
        } else if (arg == "-cn") {
            if (i+1 < argc) p.cn = atof(argv[++i]);
        } else if (arg == "-pow") {
            if (i+1 < argc) p.pow = atoi(argv[++i]);
        } else if (arg == "-sig") {
            if (i+1 < argc) { p.sig = atof(argv[++i]); p.sig_set = true; }
        } else if (arg == "-eps") {
            if (i+1 < argc) { p.eps = atof(argv[++i]); p.eps_set = true; }
        } else if (arg == "-A") {
            if (i+1 < argc) p.A = atof(argv[++i]);
        } else if (arg == "-B") {
            if (i+1 < argc) p.B = atof(argv[++i]);
        } else if (arg == "-C") {
            if (i+1 < argc) p.C = atof(argv[++i]);
        } else if (arg == "-qi") {
            if (i+1 < argc) p.qi = atof(argv[++i]);
        } else if (arg == "-qj") {
            if (i+1 < argc) p.qj = atof(argv[++i]);
        } else if (arg == "-sigfac") {
            if (i+1 < argc) p.sigfac = atof(argv[++i]);
        } else if (arg == "-w") {
            p.w = true;
        } else if (arg == "-now") {
            p.w = false;
        } else if (arg == "-xvg") {
            i++;  // skip value
        } else if (arg == "-nobackup") {
            p.backup = false;
        } else if (arg == "-backup") {
            p.backup = true;
        } else if (arg.substr(0,4) == "-no") {
            // Ignore -no prefix options we don't recognize
        } else {
            fprintf(stderr, "\n-------------------------------------------------------\n");
            fprintf(stderr, "Program:     %s, version %s\n", prog_name.c_str(), GMX_VERSION);
            fprintf(stderr, "Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\n");
            fprintf(stderr, "Function:    void gmx::CommandLineParser::parse(int*, char**)\n");
            fprintf(stderr, "\nError in user input:\n");
            fprintf(stderr, "Invalid command-line options\n");
            fprintf(stderr, "    Unknown command-line option %s\n", arg.c_str());
            fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
            fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
            fprintf(stderr, "-------------------------------------------------------\n");
            return 1;
        }
    }

    // Compute parameters
    double c6_calc, c12_calc, sigma_calc, epsilon_calc;

    if (p.sig_set || p.eps_set) {
        // User set sig or eps: compute c6/c12 from sig/eps
        sigma_calc = p.sig;
        epsilon_calc = p.eps;
        c6_calc = 4.0 * epsilon_calc * pow(sigma_calc, 6);
        c12_calc = 4.0 * epsilon_calc * pow(sigma_calc, 12);
    } else {
        // No sig/eps set: use c6/cn
        c6_calc = p.c6;
        c12_calc = p.cn;  // cn is the C12 term
        sigma_calc = 0.0;
        epsilon_calc = 0.0;
    }

    // If we used c6/cn, compute sigma/epsilon from them  
    if (!p.sig_set && !p.eps_set && c6_calc > 0 && c12_calc > 0) {
        sigma_calc = pow(c12_calc / c6_calc, 1.0/6.0);
        epsilon_calc = c6_calc / (4.0 * pow(sigma_calc, 6));
    }

    // Compute VdW minimum
    double r_min = 0.0, V_min = 0.0;
    if (sigma_calc > 0) {
        r_min = sigma_calc * pow(2.0, 1.0/6.0);
        V_min = c12_calc / pow(r_min, 12) - c6_calc / pow(r_min, 6);
    }

    // Buckingham fit: A*exp(-B*r) - C/r^6 ~ C12/r^12 - C6/r^6
    // At r_min: A*exp(-B*r_min) = C12/r_min^12 = epsilon
    // B = 12/r_min
    double bkA = 0.0, bkB = 0.0, bkC = c6_calc;
    if (r_min > 0) {
        bkB = 12.0 / r_min;
        bkA = epsilon_calc * exp(bkB * r_min);
    }

    // Print results to stdout
    printf("c6    = %12.6g, c12    = %12.6g\n", c6_calc, c12_calc);
    printf("sigma = %12.5f, epsilon = %12.5f\n", sigma_calc, epsilon_calc);

    if (r_min > 0) {
        printf("Van der Waals minimum at %g, V = %g\n\n", r_min, V_min);
    } else {
        printf("Van der Waals minimum at 0, V = -nan\n\n");
    }

    printf("Fit of Lennard Jones (12-6) to Buckingham:\n");
    if (r_min > 0) {
        printf("A = %g, B = %g, C = %g\n", bkA, bkB, bkC);
    } else {
        printf("A = -nan, B = inf, C = %g\n", c6_calc);
    }

    // Handle charges if set
    if (p.qi != 0.0 || p.qj != 0.0) {
        // Coulomb constant in GROMACS units: kJ/mol*nm/e^2
        double ke = 138.935458;
        // Find minimum of LJ + Coulomb
        // V_total(r) = C12/r^12 - C6/r^6 + ke*qi*qj/r
        // Numerical minimization
        double rmin_tot = 0.0;
        double vmin_tot = 1e30;
        if (r_min > 0) {
            double rstart = p.sigfac * sigma_calc;
            for (int k = 0; k < 1000; k++) {
                double r = rstart + k * 0.001 * r_min;
                if (r < 1e-10) continue;
                double v = c12_calc / pow(r, 12) - c6_calc / pow(r, 6) + ke * p.qi * p.qj / r;
                if (v < vmin_tot) {
                    vmin_tot = v;
                    rmin_tot = r;
                }
            }
        }
        printf("Van der Waals + Coulomb minimum at r = %g (nm). Value = %g (kJ/mol)\n",
               rmin_tot, vmin_tot);
    }

    // Write XVG file
    std::string outpath = p.outfile;
    if (p.backup) {
        std::string bak = backup_file(outpath);
        if (!bak.empty()) {
            fprintf(stderr, "\nBack Off! I just backed up %s to %s\n", outpath.c_str(), bak.c_str());
        }
    }

    FILE* xvgfp = fopen(outpath.c_str(), "w");
    if (!xvgfp) {
        fprintf(stderr, "\n-------------------------------------------------------\n");
        fprintf(stderr, "Program:     gmx sigeps, version %s\n", GMX_VERSION);
        fprintf(stderr, "Source file: src/gromacs/utility/futil.cpp (line 414)\n");
        fprintf(stderr, "\nFile input/output error:\n%s\n", outpath.c_str());
        fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
        fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
        fprintf(stderr, "-------------------------------------------------------\n");
        return 1;
    }

    write_xvg_header(xvgfp, argv0, argc, argv, "Potential", "r (nm)", "E (kJ/mol)",
                     "Lennard-Jones", r_min > 0 ? "Buckingham" : NULL);

    // Generate data points
    double r1 = (sigma_calc > 0) ? p.sigfac * sigma_calc : p.sigfac * 0.25;
    if (r1 <= 0) r1 = 0.175;  // fallback
    double step = 0.005;
    if (sigma_calc > 0) step = 0.006;

    for (int k = 0; k < 100; k++) {
        double r = r1 + k * step;
        double v_lj = c12_calc / pow(r, 12) - c6_calc / pow(r, 6);
        double v_bk = (r_min > 0) ? bkA * exp(-bkB * r) - bkC / pow(r, 6) : 0.0;

        if (r_min > 0) {
            fprintf(xvgfp, "%10g%12g%12g\n", r, v_lj, v_bk);
        } else {
            fprintf(xvgfp, "%10g%12g        -nan\n", r, v_lj);
        }
    }

    fclose(xvgfp);

    if (!quiet) print_quote(stderr);

    return 0;
}

