    if (times.size() >= 2) dt = times[1] - times[0];

    printf("Read %d sets of %d points, dt = %g\n\n", nsets, npts, dt);

    // Print stats header
    printf("                                      std. dev.    relative deviation of\n");
    printf("                       standard       ---------   cumulants from those of\n");
    printf("set      average       deviation      sqrt(n-1)   a Gaussian distribition\n");
    printf("                                                      cum. 3   cum. 4\n");

    // Compute stats for each set
    for (int s = 0; s < nsets; s++) {
        const std::vector<double>& dat = datasets[s];
        int n = (int)dat.size();
        if (n == 0) continue;

        double sum = 0;
        for (int k = 0; k < n; k++) sum += dat[k];
        double mean = sum / n;

        double sum2 = 0;
        for (int k = 0; k < n; k++) sum2 += (dat[k]-mean)*(dat[k]-mean);
        double m2 = sum2 / n;
        double sigma = sqrt(m2);

        double sum3 = 0, sum4 = 0;
        for (int k = 0; k < n; k++) {
