    bool deriv;
};

static int run_analyze(const char* argv0, int argc, char** argv, bool quiet) {
    std::string prog_name = std::string("gmx ") + get_prog_name(argv0);

    AnalyzeParams ap;
    ap.infile = "";
    ap.btime = -1;
    ap.etime = -1;
    ap.nsets = 1;
    ap.use_time = true;
    ap.deriv = false;

    // Parse arguments
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "-help") {
            printf("%s", ANALYZE_HELP);
            return 0;
        } else if (arg == "-version") {
            do_print_version(stdout, argv0, argc, argv);
            return 0;
        } else if (arg == "-f") {
            if (i+1 < argc) {
                ap.infile = argv[++i];
                // Check extension
                std::string& fn = ap.infile;
                size_t dot = fn.rfind('.');
                if (dot != std::string::npos) {
                    std::string ext = fn.substr(dot+1);
                    if (ext != "xvg") {
                        fprintf(stderr, "\n-------------------------------------------------------\n");
                        fprintf(stderr, "Program:     gmx analyze, version %s\n", GMX_VERSION);
                        fprintf(stderr, "Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\n");
                        fprintf(stderr, "Function:    void gmx::CommandLineParser::parse(int*, char**)\n");
                        fprintf(stderr, "\nError in user input:\n");
                        fprintf(stderr, "Invalid command-line options\n");
                        fprintf(stderr, "  In command-line option -f\n");
                        fprintf(stderr, "    File name '%s' cannot be used for this option.\n", fn.c_str());
                        fprintf(stderr, "    Only the following extensions are possible:\n");
                        fprintf(stderr, "      .xvg\n");
                        fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
                        fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
                        fprintf(stderr, "-------------------------------------------------------\n");
                        return 1;
                    }
                }
            }
        } else if (arg == "-b") {
            if (i+1 < argc) ap.btime = atof(argv[++i]);
        } else if (arg == "-e") {
            if (i+1 < argc) ap.etime = atof(argv[++i]);
        } else if (arg == "-n") {
            if (i+1 < argc) ap.nsets = atoi(argv[++i]);
        } else if (arg == "-time") {
            ap.use_time = true;
        } else if (arg == "-notime") {
            ap.use_time = false;
        } else if (arg == "-d") {
            ap.deriv = true;
        } else if (arg == "-nod") {
            ap.deriv = false;
        } else if (arg.substr(0,2) == "-[") {
            // ignore
        } else if (arg[0] == '-') {
            // Skip optional arg values
            bool skip_next = (arg == "-ac" || arg == "-msd" || arg == "-cc" ||
                              arg == "-dist" || arg == "-av" || arg == "-ee" ||
                              arg == "-fitted" || arg == "-g" || arg == "-xvg" ||
                              arg == "-bw" || arg == "-errbar" || arg == "-aver_start" ||
                              arg == "-temp" || arg == "-fitstart" || arg == "-fitend" ||
                              arg == "-filter" || arg == "-acflen" || arg == "-P" ||
                              arg == "-fitfn" || arg == "-beginfit" || arg == "-endfit");
            if (skip_next && i+1 < argc) {
                std::string next = argv[i+1];
                if (next[0] != '-') i++;
            }
        }
    }

    if (ap.infile.empty()) {
        // Try default file
        ap.infile = "graph.xvg";
    }

    // Read the XVG file
    FILE* fp = fopen(ap.infile.c_str(), "r");
    if (!fp) {
        fprintf(stderr, "\n-------------------------------------------------------\n");
        fprintf(stderr, "Program:     gmx analyze, version %s\n", GMX_VERSION);
        fprintf(stderr, "Source file: src/gromacs/options/options.cpp (line 184)\n");
        fprintf(stderr, "Function:    void gmx::internal::OptionSectionImpl::finish()\n");
        fprintf(stderr, "\nError in user input:\n");
        fprintf(stderr, "Invalid input values\n");
        fprintf(stderr, "  In option f\n");
        fprintf(stderr, "    Required option was not provided, and the default file '%s' does not\n",
                "graph");
        fprintf(stderr, "    exist or is not accessible.\n");
        fprintf(stderr, "    The following extensions were tried to complete the file name:\n");
        fprintf(stderr, "      .xvg\n");
        fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
        fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
        fprintf(stderr, "-------------------------------------------------------\n");
        return 1;
    }

    // Parse the file
    std::vector<std::vector<double>> datasets;  // datasets[set][point]
    std::vector<double> times;

    char line[4096];
    bool checked_time = false;
    bool has_time_col = ap.use_time;

    while (fgets(line, sizeof(line), fp)) {
        // Skip comments and @ lines
        if (line[0] == '#' || line[0] == '@') continue;
        if (line[0] == '&') {
            // Dataset separator (not handled here)
            continue;
        }

        // Parse numbers
        std::vector<double> vals;
        char* p2 = line;
        while (*p2) {
            while (*p2 == ' ' || *p2 == '\t') p2++;
            if (*p2 == '\0' || *p2 == '\n' || *p2 == '\r') break;
            char* end;
            double v = strtod(p2, &end);
            if (end == p2) break;
            vals.push_back(v);
            p2 = end;
        }

        if (vals.empty()) continue;

        // Check if first line has time
        if (!checked_time && ap.use_time) {
            checked_time = true;
            if (vals.size() == 1) {
                // Only one value, no time
                has_time_col = false;
                fprintf(stderr, "\nFound only 1 number on line, assuming no time is present.\n");
            }
        }

        double t = 0.0;
        size_t start = 0;
        if (has_time_col) {
            t = vals[0];
            start = 1;
        }

        // Apply time filter
        if (ap.btime >= 0 && t < ap.btime) continue;
        if (ap.etime >= 0 && t > ap.etime) continue;

        // Add data to datasets
        times.push_back(t);
        for (size_t k = start; k < vals.size(); k++) {
            size_t set_idx = k - start;
            while (datasets.size() <= set_idx) datasets.push_back(std::vector<double>());
            datasets[set_idx].push_back(vals[k]);
        }

        // If no time column, the first col is a dataset
        if (!has_time_col) {
            size_t set_idx = 0;
            while (datasets.size() <= set_idx) datasets.push_back(std::vector<double>());
            if (datasets[0].empty() || datasets[0].size() < times.size()) {
                datasets[0].push_back(vals[0]);
            }
            for (size_t k = 1; k < vals.size(); k++) {
                size_t si = k;
                while (datasets.size() <= si) datasets.push_back(std::vector<double>());
                datasets[si].push_back(vals[k]);
            }
        }
    }
    fclose(fp);

    // Fix-up for no-time case
    if (!has_time_col) {
        // Rebuild datasets properly
        // The line parsing above is messy - let's redo it
        datasets.clear();
        times.clear();

        FILE* fp2 = fopen(ap.infile.c_str(), "r");
        if (!fp2) return 1;

        while (fgets(line, sizeof(line), fp2)) {
            if (line[0] == '#' || line[0] == '@' || line[0] == '&') continue;

            std::vector<double> vals;
            char* p2 = line;
            while (*p2) {
                while (*p2 == ' ' || *p2 == '\t') p2++;
                if (*p2 == '\0' || *p2 == '\n' || *p2 == '\r') break;
                char* end;
                double v = strtod(p2, &end);
                if (end == p2) break;
                vals.push_back(v);
                p2 = end;
            }

            if (vals.empty()) continue;

            double t = (double)times.size();
            times.push_back(t);

            for (size_t k = 0; k < vals.size(); k++) {
                while (datasets.size() <= k) datasets.push_back(std::vector<double>());
                datasets[k].push_back(vals[k]);
            }
        }
        fclose(fp2);
    } else if (ap.use_time) {
        // Redo with correct time handling
        datasets.clear();
        times.clear();

        FILE* fp2 = fopen(ap.infile.c_str(), "r");
        if (!fp2) return 1;

        bool check_done = false;
        bool found_time = true;

        while (fgets(line, sizeof(line), fp2)) {
            if (line[0] == '#' || line[0] == '@' || line[0] == '&') continue;

            std::vector<double> vals;
            char* p2 = line;
            while (*p2) {
                while (*p2 == ' ' || *p2 == '\t') p2++;
                if (*p2 == '\0' || *p2 == '\n' || *p2 == '\r') break;
                char* end;
                double v = strtod(p2, &end);
                if (end == p2) break;
                vals.push_back(v);
                p2 = end;
            }

            if (vals.empty()) continue;

            if (!check_done) {
                check_done = true;
                if (vals.size() == 1) {
                    found_time = false;
                    fprintf(stderr, "\nFound only 1 number on line, assuming no time is present.\n");
                }
            }

            double t;
            size_t start;
            if (found_time) {
                t = vals[0];
                start = 1;
            } else {
                t = (double)times.size();
                start = 0;
            }

            if (ap.btime >= 0 && t < ap.btime) continue;
            if (ap.etime >= 0 && t > ap.etime) continue;

            times.push_back(t);
            for (size_t k = start; k < vals.size(); k++) {
                size_t si = k - start;
                while (datasets.size() <= si) datasets.push_back(std::vector<double>());
                datasets[si].push_back(vals[k]);
            }
        }
        fclose(fp2);
    }

    if (datasets.empty() || datasets[0].empty()) {
        fprintf(stderr, "No data read from %s\n", ap.infile.c_str());
        return 1;
    }

    int npts = (int)datasets[0].size();
    int nsets = (int)datasets.size();

    // Compute dt
    double dt = 1.0;
    if (times.size() >= 2) dt = times[1] - times[0];

    printf("Read %d sets of %d points, dt = %g\n\n", nsets, npts, dt);

    // Print stats header
    printf("                                      std. dev.    relative deviation of\n");
    printf("                       standard       ---------   cumulants from those of\n");
    printf("set      average       deviation      sqrt(n-1)   a Gaussian distribition\n");
    printf("                                                      cum. 3   cum. 4\n");

    // Compute stats for each set
    for (int s = 0; s < nsets; s++) {
        const std::vector<double>& dat = datasets[s];
        int n = (int)dat.size();
        if (n == 0) continue;

        double sum = 0;
        for (int k = 0; k < n; k++) sum += dat[k];
        double mean = sum / n;

        double sum2 = 0;
        for (int k = 0; k < n; k++) sum2 += (dat[k]-mean)*(dat[k]-mean);
        double m2 = sum2 / n;
        double sigma = sqrt(m2);

        double sum3 = 0, sum4 = 0;
        for (int k = 0; k < n; k++) {
            double d = dat[k] - mean;
            sum3 += d*d*d;
            sum4 += d*d*d*d;
        }
        double m3 = sum3 / n;
        double m4 = sum4 / n;

        double cum3 = (sigma > 0) ? m3 / (sigma*sigma*sigma) : 0.0;
        double cum4 = (m2 > 0) ? m4 / (3.0*m2*m2) - 1.0 : 0.0;
        double std_n1 = (n > 1) ? sigma / sqrt((double)(n-1)) : 0.0;

        printf("SS%-2d  %14.6e  %14.6e  %14.6e  %8.3f  %8.3f\n",
               s+1, mean, sigma, std_n1, cum3, cum4);
    }
    printf("\n");

    if (!quiet) print_quote(stderr);
    return 0;
}

