static int run_help(const char* argv0, int argc, char** argv, bool quiet) {
    if (argc <= 1) {
        // Just "help" with no args
        printf("%s", MAIN_HELP);
        if (!quiet) print_quote(stderr);
        return 0;
    }

    std::string topic = argv[1];

    if (topic == "commands") {
        printf("%s", COMMANDS_HELP);
        if (!quiet) print_quote(stderr);
        return 0;
    }

    if (topic == "selections") {
        if (argc > 2) {
            std::string subtopic = argv[2];
            // Subtopics
            if (subtopic == "arithmetic") {
                printf("ARITHMETIC EXPRESSIONS IN SELECTIONS\n\n");
                printf("Basic arithmetic evaluation is supported for numeric expressions. Supported\n");
                printf("operations are addition, subtraction, negation, multiplication, division, and\n");
                printf("exponentiation (using ^). Result of a division by zero or other illegal\n");
                printf("operations is undefined.\n");
            } else if (subtopic == "cmdline") {
                printf("SPECIFYING SELECTIONS FROM COMMAND LINE\n\n");
                printf("If no selections are provided on the command line, you are prompted to type\n");
                printf("the selections interactively (a pipe can also be used to provide the\n");
                printf("selections in this case for most tools). While this works well for testing, it\n");
                printf("is easier to provide the selections from the command line if they are complex\n");
                printf("or for scripting.\n\n");
                printf("Each tool has different command-line arguments for specifying selections (see\n");
                printf("the help for the individual tools). You can either pass a single string\n");
                printf("containing all selections (separated by semicolons), or multiple strings, each\n");
                printf("containing one selection. Note that you need to quote the selections to\n");
                printf("protect them from the shell.\n\n");
                printf("If you set a selection command-line argument, but do not provide any\n");
                printf("selections, you are prompted to type the selections for that argument\n");
                printf("interactively. This is useful if that selection argument is optional, in which\n");
                printf("case it is not normally prompted for.\n\n");
                printf("To provide selections from a file, use -sf file.dat in the place of the\n");
                printf("selection for a selection argument (e.g., -select -sf file.dat). In general,\n");
                printf("the -sf argument reads selections from the provided file and assigns them to\n");
                printf("selection arguments that have been specified up to that point, but for which\n");
                printf("no selections have been provided. As a special case, -sf provided on its own,\n");
                printf("without preceding selection arguments, assigns the selections to all (yet\n");
                printf("unset) required selections (i.e., those that would be prompted interactively\n");
            } else {
                printf("Unknown subtopic: %s\n", subtopic.c_str());
            }
        } else {
            printf("%s", SEL_HELP);
        }
        if (!quiet) print_quote(stderr);
        return 0;
    }

    // Help for specific command
    // These are the major help texts
    if (topic == "sigeps") {
        printf("%s", SIGEPS_HELP);
    } else if (topic == "analyze") {
        printf("%s", ANALYZE_HELP);
    } else {
        // Generic help for unknown commands - just say it's a command
        printf("Help is available for the following command:\n\n");
        printf("Use 'gmx %s -h' for help on this command.\n", topic.c_str());
    }

    if (!quiet) print_quote(stderr);
    return 0;
}

// ============================================================
// MAIN FUNCTION
// ============================================================

int main(int argc, char** argv) {
    std::string prog = get_prog_name(argv[0]);

    // Parse global options first
    bool show_help = false;
    bool show_version = false;
    bool show_copyright = false;
    bool quiet = false;
    bool backup = true;
    int  nice_level = 19;
    std::string command = "";
    int cmd_argc = 0;
    char** cmd_argv = nullptr;
    int cmd_start = 0;

    // Collect args for the sub-program invocation
    std::vector<std::string> all_args(argv+1, argv+argc);

    // First pass: find global options and command
    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "-help") {
            show_help = true;
        } else if (arg == "-noh" || arg == "-nohelp") {
            show_help = false;
        } else if (arg == "-version") {
            show_version = true;
        } else if (arg == "-noversion") {
            show_version = false;
        } else if (arg == "-copyright") {
            show_copyright = true;
        } else if (arg == "-nocopyright") {
            show_copyright = false;
        } else if (arg == "-quiet") {
            quiet = true;
        } else if (arg == "-noquiet") {
            quiet = false;
        } else if (arg == "-backup") {
            backup = true;
        } else if (arg == "-nobackup") {
            backup = false;
        } else if (arg == "-nice") {
            if (i+1 < argc) { nice_level = atoi(argv[++i]); }
        } else if (arg[0] != '-') {
            // This is the command
            command = arg;
            cmd_start = i;
            break;
        } else {
            // Unknown global option
            print_banner(stderr, prog.c_str());
            if (!quiet) {
                print_startup(stderr, argv[0], argc, argv, cmd_start);
            }
            fprintf(stderr, "\n-------------------------------------------------------\n");
            fprintf(stderr, "Program:     %s, version %s\n", prog.c_str(), GMX_VERSION);
            fprintf(stderr, "Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\n");
            fprintf(stderr, "Function:    void gmx::CommandLineParser::parse(int*, char**)\n");
            fprintf(stderr, "\nError in user input:\n");
            fprintf(stderr, "Invalid command-line options\n");
            fprintf(stderr, "    Unknown command-line option %s\n", arg.c_str());
            fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
            fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
            fprintf(stderr, "-------------------------------------------------------\n");
            return 1;
        }
    }

    // Handle version flag (output to stdout)
    if (show_version) {
        do_print_version(stdout, argv[0], argc, argv);
        return 0;
    }

    // If no command, show help or run as main gmx
    if (command.empty()) {
        print_banner(stderr, prog.c_str());
        if (!quiet) {
            print_startup(stderr, argv[0], argc, argv, 0);
        }

        if (show_copyright) {
            do_print_copyright(stderr, argv[0]);
            // Also print GROMACS: line
            fprintf(stderr, "GROMACS:      %s, version %s\n", prog.c_str(), GMX_VERSION);
            std::string exe = get_exec_path(argv[0]);
            std::string cwd = get_working_dir();
            fprintf(stderr, "Executable:   %s\n", exe.c_str());
            fprintf(stderr, "Data prefix:  %s\n", DATA_PREFIX);
            fprintf(stderr, "Working dir:  %s\n", cwd.c_str());
            fprintf(stderr, "Command line:\n  %s", prog.c_str());
            for (int i = 1; i < argc; i++) fprintf(stderr, " %s", argv[i]);
            fprintf(stderr, "\n");
        }

        if (!quiet) print_quote(stderr);

        // Print help to stdout
        printf("%s", MAIN_HELP);
        return 0;
    }

    // We have a command - build sub-args array
    // Sub-args: argv[cmd_start] is the command, the rest are args to it
    // But we need to pass argv[0] (executable path) + the command args
    std::vector<char*> sub_argv;
    sub_argv.push_back(argv[0]);
    for (int i = cmd_start + 1; i < argc; i++) {
        sub_argv.push_back(argv[i]);
    }

    cmd_argc = (int)sub_argv.size();
    cmd_argv = sub_argv.data();

    // Print banner for subcommand
    std::string sub_prog = "gmx " + command;
    print_banner(stderr, sub_prog.c_str());
    if (!quiet) {
        print_startup(stderr, argv[0], argc, argv, cmd_start);
    }

    // Dispatch to subcommand
    if (command == "help") {
        std::vector<char*> help_argv;
        help_argv.push_back(argv[0]);
        for (int i = cmd_start+1; i < argc; i++) help_argv.push_back(argv[i]);
        return run_help(argv[0], (int)help_argv.size(), help_argv.data(), quiet);
    } else if (command == "sigeps") {
        return run_sigeps(argv[0], cmd_argc, cmd_argv, quiet);
    } else if (command == "analyze") {
        return run_analyze(argv[0], cmd_argc, cmd_argv, quiet);
    } else {
        // Unknown command
        fprintf(stderr, "\n-------------------------------------------------------\n");
        fprintf(stderr, "Program:     %s, version %s\n", prog.c_str(), GMX_VERSION);
        fprintf(stderr, "Source file: src/gromacs/commandline/cmdlinemodulemanager.cpp (line 389)\n");
        fprintf(stderr, "Function:    gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)\n");
        fprintf(stderr, "\nError in user input:\n");
        fprintf(stderr, "'%s' is not a GROMACS command.\n", command.c_str());
        fprintf(stderr, "\nFor more information and tips for troubleshooting, please check the GROMACS\n");
        fprintf(stderr, "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n");
        fprintf(stderr, "-------------------------------------------------------\n");
        return 1;
    }

    return 0;
}

