# The Coulomb minimum search only happens when r_min > 0 (i.e., when sigma > 0).
# When sigma = 0 (default case with c6/cn), r_min = 0 so no search is done.
# 
# For the default case (c6=0.001, cn=1e-6), sigma and r_min should be computed from c6/cn.
# But in our implementation, when using defaults (no explicit c6/cn), sigma is 0.
# When -qi/-qj are given but no sig/eps/c6/cn, we have c6=0.001, cn=1e-6 (defaults).
# We need to compute sigma from these for the Coulomb search.
# 
# The fix: when computing the Coulomb minimum, use c6_calc and c12_calc even if sigma=0.

python3 << 'PYEOF'
content = open('/workspace/src/gmx.cpp', 'r').read()

old_coulomb = '''    // Handle charges if set
    if (p.qi != 0.0 || p.qj != 0.0) {
        // Coulomb constant in GROMACS units: kJ/mol*nm/e^2
        double ke = 138.935458;
        // Find minimum of LJ + Coulomb
        // V_total(r) = C12/r^12 - C6/r^6 + ke*qi*qj/r
        // Numerical minimization
        double rmin_tot = 0.0;
        double vmin_tot = 1e30;
        if (r_min > 0) {
            double rstart = p.sigfac * sigma_calc;
            for (int k = 0; k < 1000; k++) {
                double r = rstart + k * 0.001 * r_min;
                if (r < 1e-10) continue;
                double v = c12_calc / pow(r, 12) - c6_calc / pow(r, 6) + ke * p.qi * p.qj / r;
                if (v < vmin_tot) {
                    vmin_tot = v;
                    rmin_tot = r;
                }
            }
        }
        printf("Van der Waals + Coulomb minimum at r = %g (nm). Value = %g (kJ/mol)\\n",
               rmin_tot, vmin_tot);
    }'''

new_coulomb = '''    // Handle charges if set
    if (p.qi != 0.0 || p.qj != 0.0) {
        // Coulomb constant in GROMACS units: kJ/mol*nm/e^2
        double ke = 138.935458;
        // Find minimum of LJ + Coulomb by numerical search
        // V_total(r) = C12/r^12 - C6/r^6 + ke*qi*qj/r
        double rmin_tot = 0.0;
        double vmin_tot = 1e30;

        // Compute sigma for the search range (may differ from sigma_calc if using defaults)
        double sig_for_search = sigma_calc;
        if (sig_for_search == 0 && c6_calc > 0 && c12_calc > 0) {
            sig_for_search = pow(c12_calc / c6_calc, 1.0/6.0);
        }
        double rstart = (sig_for_search > 0) ? p.sigfac * sig_for_search : 0.1;
        double r_min_local = (sig_for_search > 0) ? sig_for_search * pow(2.0, 1.0/6.0) : 0.3;

        for (int k = 0; k < 1000; k++) {
            double r = rstart + k * 0.001 * r_min_local;
            if (r < 1e-10) continue;
            double v = c12_calc / pow(r, 12) - c6_calc / pow(r, 6) + ke * p.qi * p.qj / r;
            if (v < vmin_tot) {
                vmin_tot = v;
                rmin_tot = r;
            }
        }
        printf("Van der Waals + Coulomb minimum at r = %g (nm). Value = %g (kJ/mol)\\n",
               rmin_tot, vmin_tot);
    }'''

content = content.replace(old_coulomb, new_coulomb)
open('/workspace/src/gmx.cpp', 'w').write(content)
print("Fixed Coulomb minimum")
