# Our executable shows "/workspace/executable" (canonical path via readlink).
# The original showed "/workspace/./executable" when run as "./executable".
# 
# The difference is:
# - readlink("/proc/self/exe") -> "/workspace/executable" (canonical)
# - The original might use argv[0] directly: "./executable" -> becomes "/workspace/./executable"?
#   Actually "/workspace/." + "executable" = "/workspace/./executable"
#   Or maybe it uses realpath(argv[0]) but doesn't canonicalize properly?
# 
# Actually the original binary might be using a different method to get the path.
# When argv[0] is "./executable", it might be doing:
# realpath("./executable") = "/workspace/executable"
# or just prepending getcwd() + "/" + argv[0] = "/workspace/./executable"
# 
# Let me check which approach gives "/workspace/./executable":
# If argv[0] = "./executable" and we just prepend cwd:
# "/workspace" + "/" + "./executable" = "/workspace/./executable" ✓
# 
# So the original DOESN'T use /proc/self/exe but instead does cwd + "/" + argv[0]
# when argv[0] starts with "./".
# 
# Let me check: the original says "/workspace/./executable"
# Our readlink gives "/workspace/executable"
# 
# The tests might expect "/workspace/executable" or "/workspace/./executable" depending on how they call it.
# If the test calls it as "./executable", the original would show "/workspace/./executable"
# but ours shows "/workspace/executable".
# 
# This could be a test failure. Let me check what approach GROMACS uses.

# Looking at the GROMACS source code behavior:
# The executable path detection typically uses:
# 1. /proc/self/exe (Linux)
# 2. Or just returns argv[0] as-is (prepend getcwd if relative)
# 
# The original appears to use approach 2 (just concatenate).
# Let me change our get_exec_path to use that approach instead:

python3 << 'PYEOF'
content = open('/workspace/src/gmx.cpp', 'r').read()

old_exec = '''static std::string get_exec_path(const char* argv0) {
    char buf[4096];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf)-1);
    if (n > 0) { buf[n] = '\\0'; return buf; }
    return argv0;
}'''

new_exec = '''static std::string get_exec_path(const char* argv0) {
    // If argv0 is an absolute path, return as-is
    if (argv0 && argv0[0] == '/') return argv0;
    // If relative, prepend cwd
    if (argv0) {
        std::string cwd = get_working_dir();
        return cwd + "/" + argv0;
    }
    // Fallback to /proc/self/exe
    char buf[4096];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf)-1);
    if (n > 0) { buf[n] = '\\0'; return buf; }
    return argv0 ? argv0 : ".";
}'''

content = content.replace(old_exec, new_exec)
open('/workspace/src/gmx.cpp', 'w').write(content)
print("Fixed exec path")
PYEOF

